import os
import secrets
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parents[1]
INSTANCE_DIR = BASE_DIR / "instance"

APP_NAME = "ScholarPath NG"
APP_TAGLINE = "Student academic performance prediction for Nigerian tertiary institutions"

BUNDLED_DATASET = BASE_DIR / "data" / "tertiary_records_ng_simulated.csv"
BUNDLED_DATASET_NAME = "Nigeria tertiary students (simulated)"
BUNDLED_DATASET_NOTE = (
    "Simulated records generated by scripts/generate_dataset.py with a fixed "
    "seed. They are not real student records. Replace with institutional "
    "records by uploading a CSV with the same columns.")


def database_url():
    url = os.environ.get("DATABASE_URL")
    if not url:
        INSTANCE_DIR.mkdir(exist_ok=True)
        return f"sqlite:///{INSTANCE_DIR / 'scholarpath.db'}"
    # Render/Heroku style URLs
    if url.startswith("postgres://"):
        url = "postgresql://" + url[len("postgres://"):]
    # Name the driver explicitly. Newer SQLAlchemy releases pick psycopg 3
    # for a bare postgresql:// URL, while requirements.txt installs psycopg2.
    if url.startswith("postgresql://"):
        url = "postgresql+psycopg2://" + url[len("postgresql://"):]
    return url


def secret_key():
    key = os.environ.get("SECRET_KEY")
    if key:
        return key
    # Development fallback: keep one key on disk so sessions survive restarts.
    INSTANCE_DIR.mkdir(exist_ok=True)
    path = INSTANCE_DIR / "secret_key"
    if not path.exists():
        path.write_text(secrets.token_hex(32))
    return path.read_text().strip()


